// 1. Sécurité Treuil M1 instSafetyWinchM1( // 🔧 REX 2026-07-15 (2) — SIMPLIFICATION : IHM_MANU pilote désormais M1 via FB_Winch // (PRG_TREUILS_CFC), qui a BESOIN d'un SafeStop/ForbidAscent/ForbidDescent réels pour // rampé/ralentir proprement (ex-doctrine "Conditional Bypass" devenue obsolète et RETIRÉE // ici : chaque capteur/retour a DÉJÀ sa propre granularité réel/simulé — GVL_Simulation. // BusEncoderM1IsReal, SensorM1ContactorFeedbackIsReal, SensorM1ThermalIsReal, SensorTopPositionIsReal, // SensorSlackCableIsReal — un composant simulé est déjà forcé "sain" en amont (PRG_00_Inputs/ // PRG_02_Encoders), donc Enable n'a plus besoin de bypasser tout le domaine : un vrai défaut // sur un composant RÉEL protège, un composant SIMULÉ ne fait jamais défaut de lui-même). Enable := NOT PRG_MODES_CFC.Auth.InhibitM1, // 🆕 REX 2026-07-08 : Inhibit (MAINT_N2) uniquement Reset := PRG_SUPERVISION_CFC.FaultMachineReset_IHM, PowerContactorEngaged := PRG_01_Inputs_LD.PowerContactorEngaged, Mode := PRG_MODES_CFC.Auth.Mode, SyncEnable := PRG_MODES_CFC.Auth.SyncEnable, JoystickOnline := PRG_01_Diagnostics.instDiagCanOpen.DeviceJoystick.Online, JoystickOperational := PRG_01_Diagnostics.instDiagCanOpen.DeviceJoystick.Operational, HeartbeatIhmOk := PRG_01_Diagnostics.instIhmHeartbeat.HeartbeatIhmOk, EncoderAvailable := PRG_02_Encoders.instEncoderAbsM1.EncoderAvailable, EncoderFaultBypass := GVL_IHM.M1TreuilRetenue.Bypass.EncoderFault, ThermalFeedback := NOT PRG_01_Inputs_LD.M1ThermalFeedback, BrakeThermalFeedback := NOT PRG_01_Inputs_LD.BrakeThermalFeedback, // 🆕 REX 2026-07-08 — commun M1/M2/M3 SlackCableDetected := NOT PRG_01_Inputs_LD.SlackCableSwitch, PhaseRotationOk := PRG_01_Inputs_LD.PhaseRotationOk, TopPositionSensor := PRG_01_Inputs_LD.TopPositionSensor, InReferencingMode := PRG_02_Encoders.instHomingM1.Busy, CablePosM := PRG_02_Encoders.instEncoderScaleM1.CablePosM, CfgCableLimitDescentM := _WinchM1CfgPersist.CfgCableLimitDescent_M, Direction := PRG_TREUILS_CFC.M1_Direction