 BypassBrakeThermal := GVL_IHM.M1TreuilRetenue.Bypass.Global OR GVL_IHM.M1TreuilRetenue.Bypass.BrakeThermal, BypassMecaA := GVL_IHM.M1TreuilRetenue.Bypass.Global OR GVL_IHM.M1TreuilRetenue.Bypass.MecaA, BypassMecaB := GVL_IHM.M1TreuilRetenue.Bypass.Global OR GVL_IHM.M1TreuilRetenue.Bypass.MecaB, BypassMecaC := GVL_IHM.M1TreuilRetenue.Bypass.Global OR GVL_IHM.M1TreuilRetenue.Bypass.MecaC, BypassMecaD := GVL_IHM.M1TreuilRetenue.Bypass.Global OR GVL_IHM.M1TreuilRetenue.Bypass.MecaD, BypassMecaE := GVL_IHM.M1TreuilRetenue.Bypass.Global OR GVL_IHM.M1TreuilRetenue.Bypass.MecaE, BypassSafety := GVL_IHM.M1TreuilRetenue.Bypass.Global OR GVL_IHM.M1TreuilRetenue.Bypass.Safety, BypassProcess := GVL_IHM.M1TreuilRetenue.Bypass.Global OR GVL_IHM.M1TreuilRetenue.Bypass.Process, BypassTopLimitSwitch := GVL_IHM.M1TreuilRetenue.Bypass.Global OR GVL_IHM.M1TreuilRetenue.Bypass.TopLimitSwitch, BypassCableLimitSwitch := GVL_IHM.M1TreuilRetenue.Bypass.Global OR GVL_IHM.M1TreuilRetenue.Bypass.CableLimitSwitch );
// 2. Sécurité Treuil M2 instSafetyWinchM2( // 🔧 REX 2026-07-15 (2) — même simplification que M1 ci-dessus (voir bandeau instSafetyWinchM1). Enable := NOT PRG_MODES_CFC.Auth.InhibitM2, // 🆕 REX 2026-07-08 : Inhibit (MAINT_N2) uniquement Reset := PRG_SUPERVISION_CFC.FaultMachineReset_IHM, PowerContactorEngaged := PRG_01_Inputs_LD.PowerContactorEngaged, Mode := PRG_MODES_CFC.Auth.Mode, SyncEnable := PRG_MODES_CFC.Auth.SyncEnable, JoystickOnline := PRG_01_Diagnostics.instDiagCanOpen.DeviceJoystick.Online, JoystickOperational := PRG_01_Diagnostics.instDiagCanOpen.DeviceJoystick.Operational, HeartbeatIhmOk := PRG_01_Diagnostics.instIhmHeartbeat.HeartbeatIhmOk, EncoderAvailable := PRG_02_Encoders.instEncoderAbsM2.EncoderAvailable, EncoderFaultBypass := GVL_IHM.M2TreuilBenne.Bypass.EncoderFault, ThermalFeedback := NOT PRG_01_Inputs_LD.M2ThermalFeedback, BrakeThermalFeedback := NOT PRG_01_Inputs_LD.BrakeThermalFeedback, // 🆕 REX 2026-07-08 — commun M1/M2/M3 SlackCableDetected := NOT PRG_01_Inputs_LD.SlackCableSwitch, PhaseRotationOk := PRG_01_Inputs_LD.PhaseRotationOk, TopPositionSensor := PRG_01_Inputs_LD.TopPositionSensor, InReferencingMode := PRG_02_Encoders.instHomingM2.Busy, CablePosM := PRG_02_Encoders.instEncoderScaleM2.CablePosM, CfgCableLimitDescentM := _WinchM2CfgPersist.CfgCableLimitDescent_M, Direction := PRG_TREUILS_CFC.M2_Direction_Active, MovementCommanded := PRG_TREUILS_CFC.instWinchM2.RelayFwd OR PRG_TREUILS_CFC.instWinchM2.RelayRev, Homed := PRG_02_Encoders.instHomingM2.Homed, HomingSuspect := PRG_02_Encoders.instHomingM2.HomingSuspect, TopLimitM := _WinchM2CfgPersist.CfgTopSensorPos_M, // 🔧 REX 2026-07-07 — Méca A/B (voir FB_Safety_Winch bandeau en-tête) — Méca C NON applicable // à M2 (c'est M2 qui bouge pendant le benne, BenneHoldStillActive reste FALSE) FwdRevSpeedFeedbackOff := PRG_01_Inputs_LD.M2FwdRevSpeedFeedbackOff, BrakeFeedback := PRG_01_Inputs_LD.M2BrakeFeedback, // 🔧 REX 2026-07-19 : idem M1 (voir bandeau instSafetyWinchM1 ci-dessus) — suppression IHM_MANU. JoystickYNeutral := (ABS(PRG_01_Diagnostics.instJoystick.AxisCmdY.SpeedRef) < 0.1), BenneHoldStillActive := FALSE, // 🔧 REX 2026-07-08 (5) : BUG CORRIGÉ — oublié côté M2 lors de l'ajout initial Méca E. // ExpectedOtherWinchPosM valait 0.0 par défaut (non câblé) → Méca E comparait CablePosM2 // à 0 au lieu de M1, déclenchement permanent dès que M2 > CriticalSyncToleranceM (2.0m) // du zéro codeur. M1 corrigé de l'offset benne actif, ramené dans le référentiel M2. ExpectedOtherWinchPosM := PRG_02_Encoders.instEncoderScaleM1.CablePosM + PRG_TREUILS_CFC.instBucket.ActiveOffsetM, BenneBusy := PRG_TREUILS_CFC.instBucket.Busy, CriticalSyncToleranceM := _WinchCriticalSyncTolerance_M, OtherWinchInhibited := PRG_MODES_CFC.Auth.InhibitM1, // 🆕 REX 2026-07-08 (7) MeasuredSpeedMps := PRG_02_Encoders.M2MeasuredSpeed_Mps, MeasuredSpeedSignedMps := PRG_02_Encoders.M2MeasuredSpeedSigned_Mps, MeasuredSpeedValid := PRG_02_Encoders.M2SpeedValid, BypassGlobal := GVL_IHM.M2TreuilBenne.Bypass.Global, BypassOperatorComm := GVL_IHM.M2TreuilBenne.Bypass.Global OR GVL_IHM.M2TreuilBenne.Bypass.OperatorComm, BypassPhaseRotation := GVL_IHM.M2TreuilBenne.Bypass.Global OR GVL_IHM.M2TreuilBenne.Bypass.PhaseRotation, BypassBrakeThermal := GVL_IHM.M2TreuilBenne.Bypass.Global OR GVL_IHM.M2TreuilBenne.Bypass.BrakeThermal, BypassMecaA := GVL_IHM.M2TreuilBenne.Bypass.Global OR GVL_IHM.M2TreuilBenne.Bypass.MecaA, BypassMecaB := GVL_IHM.M2TreuilBenne.Bypass.Global OR GVL_IHM.M2TreuilBenne.Bypass.MecaB, BypassMecaC := GVL_IHM.M2TreuilBenne.Bypass.Global OR GVL_IHM.M2TreuilBenne.Bypass.MecaC, BypassMecaD := GVL_IHM.M2TreuilBenne.Bypass.Global OR GVL_IHM.M2TreuilBenne.Bypass.MecaD, BypassMecaE := GVL_IHM.M2TreuilBenne.Bypass.Global OR GVL_IHM.M2TreuilBenne.Bypass.MecaE, BypassSafety := GVL_IHM.M2TreuilBenne.Bypass.Global OR GVL_IHM.M2TreuilBenne.Bypass.Safety, BypassProcess := GVL_IHM.M2TreuilBenne.Bypass.Global OR GVL_IHM.M2TreuilBenne.Bypass.Process, BypassTopLimitSwitch := GVL_IHM.M2TreuilBenne.Bypass.Global OR GVL_IHM.M2TreuilBenne.Bypass.TopLimitSwitch, BypassCableLimitSwitch := GVL_IHM.M2TreuilBenne.Bypass.Global OR GVL_IHM.M2TreuilBenne.Bypass.CableLimitSwitch );
// 2bis. Moniteurs vitesse — diagnostic seul ; seuils désactivés jusqu'à T45. instSpeedMonitorM1( Enable := NOT PRG_MODES_CFC.Auth.InhibitM1 AND PRG_02_Encoders.M1SpeedValid, Reset := PRG_SUPERVISION_CFC.FaultMachineReset_IHM, PowerContactorEngaged := PRG_01_Inputs_LD.PowerContactorEngaged, Mode := PRG_MODES_CFC.Auth.Mode, SpeedMps := PRG_02_Encoders.M1MeasuredSpeed_Mps, SpeedVariationThresholdMps := 0.0, SpeedVariationTimeout := T#0ms, SpeedStabilityTimeout := T#0ms ); instSpeedMonitorM2( Enable := NOT PRG_MODES_CFC.Auth.InhibitM2 AND PRG_02_Encoders.M2SpeedValid, Reset := PRG_SUPERVISION_CFC.FaultMachineReset_IHM, PowerContactorEngaged := PRG_01_Inputs_LD.PowerContactorEngaged, Mode := PRG_MODES_CFC.Auth.Mode, SpeedMps := PRG_02_Encoders.M2MeasuredSpeed_Mps, SpeedVariationThresholdMps := 0.0, SpeedVariationTimeout := T#0ms, SpeedStabilityTimeout := T#0ms );
// 2ter. Estimation charge — information empirique, jamais une fonction safety. instLoadEstimatorM1( Enable := NOT PRG_MODES_CFC.Auth.InhibitM1 AND PRG_02_Encoders.M1SpeedValid, Reset := PRG_SUPERVISION_CFC.FaultMachineReset_IHM, PowerContactorEngaged := PRG_01_Inputs_LD.PowerContactorEngaged, Mode := PRG_MODES_CFC.Auth.Mode, ActiveSpeedStep := PRG_TREUILS_CFC.instWinchM1.StepNumber, MeasuredSpeedMps := PRG_02_Encoders.M1MeasuredSpeed_Mps, MeasuredSpeedSignedMps:= PRG_02_Encoders.M1MeasuredSpeedSigned_Mps, SpeedConfig := _WinchSpeedConfig, LoadTable := _WinchLoadEstimateTable ); instLoadEstimatorM2( Enable := NOT PRG_MODES_CFC.Auth.InhibitM2 AND PRG_02_Encoders.M2SpeedValid, Reset := PRG_SUPERVISION_CFC.FaultMachineReset_IHM, PowerContactorEngaged := PRG_01_Inputs_LD.PowerContactorEngaged, Mode := PRG_MODES_CFC.Auth.Mode, ActiveSpeedStep := PRG_TREUILS_CFC.instWinchM2.StepNumber, MeasuredSpeedMps := PRG_02_Encoders.M2MeasuredSpeed_Mps, MeasuredSpeedSignedMps:= PRG_02_Encoders.M2MeasuredSpeedSigned_Mps, SpeedConfig := _WinchSpeedConfig, LoadTable := _WinchLoadEstimateTable );
// 3. Sécurité Translation M3 instSafetyTranslationM3( // 🔧 REX 2026-07-16 — SIMPLIFICATION : IHM_MANU pilote désormais M3 via FB_Translation // (PRG_TRANSLATION_CFC), qui a BESOIN d'un SafeStop réel pour rampé/arrêter proprement // (ex-"Conditional Bypass Doctrine" RETIRÉE ici, même traitement que instSafetyWinchM1/M2 — // voir REX 2026-07-15 (2) plus haut). Pas d'InhibitM3 dans FB_Modes (contrairement à // InhibitM1/M2) : Enable inconditionnel, comme en Auto. Enable := TRUE, Reset := PRG_SUPERVISION_CFC.FaultMachineReset_IHM, PowerContactorEngaged := PRG_01_Inputs_LD.PowerContactorEngaged, Mode := PRG_MODES_CFC.Auth.Mode, JoystickOnline := PRG_01_Diagnostics.instDiagCanOpen.DeviceJoystick.Online, JoystickOperational := PRG_01_Diagnostics.instDiagCanOpen.DeviceJoystick.Operational, HeartbeatIhmOk := PRG_01_Diagnostics.instIhmHeartbeat.HeartbeatIhmOk, PhaseRotationOk := PRG_01_Inputs_LD.PhaseRotationOk, BrakeThermalFeedback := NOT PRG_01_Inputs_LD.BrakeThermalFeedback, // 🆕 REX 2026-07-08 — commun M1/M2/M3 DriveOnline := PRG_01_Diagnostics.instDiagEthercat.DeviceVariateur.Online, DriveOperational := PRG_01_Diagnostics.instDiagEthercat.DeviceVariateur.Operational, DriveStatusWord := PRG_02_Acquisition_CFC.M3_StatusWord_Filtered, DriveActualFreqHz := UINT_TO_REAL(PRG_02_Acquisition_CFC.M3_ActualFrequencyHz_Filtered) / 100.0, BrakeFeedback := PRG_01_Inputs_LD.M3BrakeFeedback, BrakeCmd := GVL_Global.instTranslationOutputInterlock_LD.BrakeCmd, Direction := PRG_TRANSLATION_CFC.M3_Direction_Active, // 🆕 REX 2026-07-18 : limites extrêmes dérivées du décodage 5 capteurs (mot valide), plus // câblées directement sur un capteur brut — voir FB_Translation_PositionDecoder. LimitSwitchFwd := PRG_02_Acquisition_CFC.M3_LimitSwitchFwd, LimitSwitchRev := PRG_02_Acquisition_CFC.M3_LimitSwitchRev, SensorWordIncoherent := PRG_02_Acquisition_CFC.M3_SensorWordIncoherent, // 🔧 Bypass des surveillances (GVL_IHM.TranslationM3.Bypass - pilotés IHM) BypassGlobal := GVL_IHM.TranslationM3.Bypass.Global, BypassOperatorComm := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.OperatorComm, BypassDriveComm := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.DriveComm, BypassPhaseRotation := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.PhaseRotation, BypassBrakeThermal := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.BrakeThermal, BypassMecaB := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.MecaB, BypassMecaA := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.MecaA, BypassLimitSwitch := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.LimitSwitch, BypassSensorIncoherent:= GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.SensorIncoherent, BypassSafety := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.Safety, BypassProcess := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.Process );

// === IMPLEMENTATION (corps du PROGRAM PRG_SUPERVISION_CFC) ===

// ── 0. HORLOGE CLIGNOTEMENT SYSTÈME (GVL_Global.BlinkClock) ───────────────
// 🧩 Réutilisation lib Util (Partie3 §0) : bloc standard BLINK, pas de TON maison —
// gère nativement un rythme allumé/éteint ASYMÉTRIQUE (TimeHigh ≠ TimeLow), contrairement
// au motif TON manuel de FB_Output.st (symétrique 500/500, propre à l'option relais).
// 🔧 REX 2026-07-16 : durées réglables sans recompiler (GVL_PERSISTENT._BlinkTimeOn/_BlinkTimeOff,
// défaut 1s allumé / 800ms éteint) — un seul rythme partagé pour tous les voyants IHM/diag qui
// clignotent pareil.
// 💡 Un voyant a besoin d'un AUTRE rythme ? Instancier son propre BLINK localement (Util) avec
// ses propres TimeHigh/TimeLow — ne pas détourner ce bit partagé pour un rythme différent.
instBlink1Hz(
    ENABLE   := TRUE,
    TIMEHIGH := _BlinkTimeOn,
    TIMELOW  := _BlinkTimeOff
);
GVL_Global.BlinkClock := instBlink1Hz.OUT;


// ── 1. ACQUISITION DES DEMANDES / BOUTONS DE L'IHM ────────────────────────
StubTranslationPositionSelect_IHM          := GVL_IHM.TranslationM3.Cmd.SelTarget;

// Signal d'acquittement défauts domaine sécurité/métier — JAMAIS Modes/Cycle (REX 2026-07-07)
FaultMachineReset_IHM := GVL_IHM.Modes.Cmd.BtnFaultReset
                    OR GVL_IHM.M1TreuilRetenue.Cmd.BtnReset
                    OR GVL_IHM.M2TreuilBenne.Cmd.BtnReset
                    OR GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnReset;


// ── 2. BRIDGES ET PERSISTANCE CONFIG (Restauration automatique) ────────────
instCfgPersistBridgeWinchM1(Hmi := GVL_IHM.M1TreuilRetenue.Cfg, Persist := _WinchM1CfgPersist);
IF instCfgPersistBridgeWinchM1.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeWinchM2(Hmi := GVL_IHM.M2TreuilBenne.Cfg, Persist := _WinchM2CfgPersist);
IF instCfgPersistBridgeWinchM2.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeSync(Hmi := GVL_IHM.M1M2Sync.Cfg, Persist := _SyncCfgPersist);
IF instCfgPersistBridgeSync.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeBucket(Hmi := GVL_IHM.M2TreuilBenne.Bucket.Cfg, Persist := _BucketCfgPersist);
IF instCfgPersistBridgeBucket.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeCommun(Hmi := GVL_IHM.Commun.Cfg, Persist := _CommunCfgPersist);
IF instCfgPersistBridgeCommun.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeCycle(Hmi := GVL_IHM.Cycle.Cfg, Persist := _CycleCfgPersist);
IF instCfgPersistBridgeCycle.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeDredgingAssist(Hmi := GVL_IHM.DredgingAssist.Cfg, Persist := _DredgingAssistCfgPersist);
IF instCfgPersistBridgeDredgingAssist.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

// 🎯 Translation M3 : persistance ciblée du seul réglage SetFreq_Hz.
// Aucun pont struct complet : BtnFwd/BtnRev restent impérativement non persistants.
IF NOT GVL_IHM.TranslationM3.Cmd.Initialized THEN
    GVL_IHM.TranslationM3.Cmd.SetFreq_Hz := _TranslationSetFreq_Hz;
    GVL_IHM.TranslationM3.Cmd.Initialized := TRUE;
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

// ── 2bis. ACQUITTEMENT RESTAURATION CONFIG (front, doctrine reset=front) ───
// 🐛 FIX 2026-07-23 : `ConfigRestoredFromPersistent` ne doit JAMAIS disparaître tout seul —
// même doctrine que les défauts métier (cause disparue + appui reset conscient pour effacer).
// Tant que l'opérateur n'a pas vérifié/acquitté, le bit reste visible à l'IHM.
instAckConfigRestored(CLK := GVL_IHM.Commun.BtnAckConfigRestored);
IF instAckConfigRestored.Q THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := FALSE;
END_IF;

// 🌐 Restauration des bypass RETAIN au boot UNIQUEMENT — co-localisation flag Initialized
// Après ça, seule la sauvegarde IHM→RETAIN fonctionne (jamais l'inverse).
// Évite le bug où une écriture IHM était écrasée par la restauration.
IF NOT GVL_IHM.TranslationM3.Bypass.Initialized THEN
    IF BypassTranslationGlobal THEN
        GVL_IHM.TranslationM3.Bypass.Global := TRUE;
    END_IF;
    GVL_IHM.TranslationM3.Bypass.Initialized := TRUE;
END_IF;

IF NOT GVL_IHM.M1TreuilRetenue.Bypass.Initialized THEN
    IF BypassWinchM1Global THEN
        GVL_IHM.M1TreuilRetenue.Bypass.Global := TRUE;
    END_IF;
    GVL_IHM.M1TreuilRetenue.Bypass.Initialized := TRUE;
END_IF;

IF NOT GVL_IHM.M2TreuilBenne.Bypass.Initialized THEN
    IF BypassWinchM2Global THEN
        GVL_IHM.M2TreuilBenne.Bypass.Global := TRUE;
    END_IF;
    GVL_IHM.M2TreuilBenne.Bypass.Initialized := TRUE;
END_IF;

// Sauvegarde synchrone vers les variables RETAIN si modifiées côté IHM
IF GVL_IHM.TranslationM3.Bypass.Global <> BypassTranslationGlobal THEN
    BypassTranslationGlobal := GVL_IHM.TranslationM3.Bypass.Global;
END_IF;
IF GVL_IHM.M1TreuilRetenue.Bypass.Global <> BypassWinchM1Global THEN
    BypassWinchM1Global := GVL_IHM.M1TreuilRetenue.Bypass.Global;
END_IF;
IF GVL_IHM.M2TreuilBenne.Bypass.Global <> BypassWinchM2Global THEN
    BypassWinchM2Global := GVL_IHM.M2TreuilBenne.Bypass.Global;
END_IF;


// ── 3. CALCULS ET ÉTATS COMMUNS POUR L'IHM ────────────────────────────────
// 🔧 REX 2026-07-07 : plus de garde Mode=SEMI_AUTO, cohérent avec PRG_TREUILS_CFC.st §5
// (la limite légale s'applique désormais dans tous les modes dès qu'elle est activée).
GVL_IHM.Commun.LimitLegalReached         := _CommunCfgPersist.LimitLegalEnabled
                                            AND ((NOT PRG_MODES_CFC.Auth.InhibitM1 AND (PRG_02_Encoders.instEncoderScaleM1.CablePosM <= _CommunCfgPersist.LimitLegalDepthMinAllowed_M))
