GVL_IHM.TranslationM3.Safety.ErrorBrakeThermal   := PRG_SAFETY_CFC.instSafetyTranslationM3.ErrorBrakeThermal;
GVL_IHM.TranslationM3.Safety.ErrorMecaB          := PRG_SAFETY_CFC.instSafetyTranslationM3.ErrorMecaB;
