GVL_IHM.DredgingAssist.State.ExtractionBusy := PRG_TREUILS_CFC.instExtractionSequence.Busy;
GVL_IHM.DredgingAssist.State.ExtractionDone := PRG_TREUILS_CFC.instExtractionSequence.Done;
GVL_IHM.DredgingAssist.State.ExtractionError := PRG_TREUILS_CFC.instExtractionSequence.Error;
GVL_IHM.DredgingAssist.State.ExtractionErrorId := PRG_TREUILS_CFC.instExtractionSequence.ErrorId;
GVL_IHM.DredgingAssist.State.ExtractionState := PRG_TREUILS_CFC.instExtractionSequence.ExtractionState;

// 🎮 Une seule consigne opérateur : l'assistant qui attend/agit a priorité sur le cycle.
IF PRG_TREUILS_CFC.instExtractionSequence.Busy
   OR PRG_TREUILS_CFC.instExtractionSequence.Ready
   OR (NOT GVL_IHM.DredgingAssist.Cmd.TglEnableDiveSearch AND GVL_IHM.DredgingAssist.Cmd.TglEnableExtractionSequence) THEN
    GVL_IHM.DredgingAssist.State.OperatorActionId := PRG_TREUILS_CFC.instExtractionSequence.OperatorActionId;
    GVL_IHM.DredgingAssist.State.OperatorAction := PRG_TREUILS_CFC.instExtractionSequence.OperatorAction;
ELSIF PRG_TREUILS_CFC.instDiveSearch.Busy
   OR PRG_TREUILS_CFC.instDiveSearch.Ready
   OR GVL_IHM.DredgingAssist.Cmd.TglEnableDiveSearch THEN
    GVL_IHM.DredgingAssist.State.OperatorActionId := PRG_TREUILS_CFC.instDiveSearch.OperatorActionId;
    GVL_IHM.DredgingAssist.State.OperatorAction := PRG_TREUILS_CFC.instDiveSearch.OperatorAction;
ELSE
    GVL_IHM.DredgingAssist.State.OperatorActionId := 0;
    GVL_IHM.DredgingAssist.State.OperatorAction := '';
END_IF;

// 🎮 Publication de l'unique consigne de conduite. Aucun FB n'écrit directement ce champ IHM.
GVL_IHM.OperatorAction.ActionId := GVL_IHM.DredgingAssist.State.OperatorActionId;
GVL_IHM.OperatorAction.Text := GVL_IHM.DredgingAssist.State.OperatorAction;

// ── 9ter. MAPPING CYCLE SEMI-AUTOMATIQUE → IHM ─────────────────────────────
GVL_IHM.Cycle.State.Ready                := PRG_05_Cycle.instCycle.Ready;
